widget.solution:
#include <vector>
#include <stdexcept>

template <typename T>
class Window {
public:
    explicit Window(int n) : n_(n) {
        if (n_ <= 0) throw std::invalid_argument("window size must be positive");
    }
    void push(T x) {
        xs_.push_back(x);
        if (static_cast<int>(xs_.size()) > n_) xs_.erase(xs_.begin());
    }
    T mean() const {
        if (xs_.empty()) throw std::logic_error("mean of an empty window");
        T total{};
        for (const T& x : xs_) total += x;
        return total / static_cast<T>(xs_.size());
    }
    int size() const { return static_cast<int>(xs_.size()); }
private:
    int n_;
    std::vector<T> xs_;
};

